import React, {useEffect, useState} from 'react';
import api from '../../lib/api';

export default function AdminProducts(){
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({name:'',slug:'',price:0,stock:0,description:''});
  const [filesById, setFilesById] = useState({});

  useEffect(()=>{ load(); },[]);

  async function load(){
    setLoading(true);
    try{
      const r = await api.get('/admin/products');
      const data = r.data;
      const list = Array.isArray(data) ? data : (Array.isArray(data?.data) ? data.data : []);
      setProducts(list);
    }catch(err){
      console.error('Load products (admin) failed:', err);
      // Show a friendly message if unauthorized or server error
      const status = err.response?.status;
      if (status === 401 || status === 403) {
        alert('Akses admin diperlukan. Silakan login sebagai admin.');
      } else {
        alert('Gagal memuat produk admin');
      }
      setProducts([]);
    } finally {
      setLoading(false);
    }
  }

  async function create(){
    await api.post('/admin/products', form);
    setForm({name:'',slug:'',price:0,stock:0,description:''});
    load();
  }

  async function remove(id){
    if (!confirm('Hapus?')) return;
    await api.delete(`/admin/products/${id}`);
    load();
  }

  function onChooseFile(e, id){
    const file = e.target.files?.[0];
    if (file){
      setFilesById(prev => ({...prev, [id]: file}));
    }
  }

  async function uploadImage(id){
    const file = filesById[id];
    if (!file) return alert('Pilih file gambar terlebih dahulu.');
    const fd = new FormData();
    fd.append('image', file);
    await api.post(`/admin/products/${id}/image`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
    alert('Gambar terunggah.');
    load();
  }

  return (
    <div style={{padding:20}}>
      <header style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
        <strong>Admin</strong>
        <nav style={{display:'flex',gap:12}}>
          <a href="/admin/products">Products</a>
          <a href="/admin/orders">Orders</a>
          <a href="#" onClick={(e)=>{e.preventDefault(); localStorage.removeItem('hr_token'); localStorage.removeItem('hr_user'); window.location.href='/admin/login';}}>Logout</a>
        </nav>
      </header>
      <h2>Admin - Products</h2>
      <div style={{display:'flex',gap:20}}>
        <div style={{flex:1}}>
          <h3>Create product</h3>
          <input placeholder="name" value={form.name} onChange={e=>setForm({...form,name:e.target.value})} />
          <input placeholder="slug" value={form.slug} onChange={e=>setForm({...form,slug:e.target.value})} />
          <input placeholder="price" type="number" value={form.price} onChange={e=>setForm({...form,price:parseInt(e.target.value||0)})} />
          <input placeholder="stock" type="number" value={form.stock} onChange={e=>setForm({...form,stock:parseInt(e.target.value||0)})} />
          <textarea placeholder="description" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} />
          <button onClick={create}>Create</button>
        </div>

        <div style={{flex:2}}>
          <h3>Products</h3>
          {loading && <div>Loading...</div>}
          <table border="1" cellPadding={8} style={{width:'100%'}}>
            <thead><tr><th>ID</th><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th>Upload</th><th>Action</th></tr></thead>
            <tbody>
              {products.map(p=> (
                <tr key={p.id}>
                  <td>{p.id}</td>
                  <td>{p.image ? <img alt="img" src={p.image} style={{width:60,height:60,objectFit:'cover'}}/> : '-'}</td>
                  <td>{p.name}</td>
                  <td>{p.price}</td>
                  <td>{p.stock}</td>
                  <td>
                    <input type="file" accept="image/*" onChange={e=>onChooseFile(e,p.id)} />
                    <button onClick={()=>uploadImage(p.id)}>Upload</button>
                  </td>
                  <td><button onClick={()=>remove(p.id)}>Delete</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}
